interface LegalDraftV3ContractDetails {
  /** Contract number. */
  contract_id?: string;
  /** Where it stands. */
  status?: "draft" | "review" | "signed" | "expired";
}

/**
 * Draft a new contract. Works on the contracts and clauses data set.
 * @param counterparty - Other party.
 * @param value - Contract value. Value must be at least 0.
 * @param term_months - Length of the term.
 * @param auto_renew - Whether it renews automatically.
 * @param contract_details - Details of the contract.
 */
declare function legal_draft_v3(counterparty: string, value: number, term_months: number, auto_renew: boolean = false, contract_details?: LegalDraftV3ContractDetails): unknown;

