}

interface CreateShipmentOrderDestinationAddress {
  /** Street and number. */
  street: string;
  /** Five-digit postcode. */
  postcode: string;
}

interface CreateShipmentItemsItem {
  /** Stock unit. */
  sku: string;
  /** Quantity. */
  qty: number;
}

/**
 * Create a shipment with a nested address and a payment method.
 * @param order - The order to ship.
 * @param payment - Card number or account id.
 * @param items - Line items.
 */
declare function create_shipment(order: CreateShipmentOrder, payment?: string | number, items?: CreateShipmentItems[]): unknown;

